// CSD_RATIONALE_BEGIN
// DIAGNOSIS OF REGRESSION (attempt 24: 10.2% accuracy vs. best 49.0%):
//
// FAILURE 1 — 9 no_span_emitted: Attempt 24 removed "<<>>" from guidance so the model
//   generated "int(formula)" in plain text and hit EOS before prefixBudget (step 800).
//   The force-open never triggered because the model stopped naturally before step 800.
//   FIX: Restore guidance with "<<int(formula)>>" examples so the model uses delimiters.
//
// FAILURE 2 — 26 tiny spans (median 1 token): The arithmetic parser accepts single
//   identifiers as complete. CloseSpanIfComplete fired after "<<n>>" (1 token). With
//   no "int()" in guidance (attempt 24), the model wrote bare variable names → 1-token
//   complete spans → wrong answer extracted.
//   FIX: SafeBoostedConstrainedStep with ["int"] boost at span start (|currentConstrained|==0).
//   "int" forces at least 4 tokens before IsCompletePrefix can return true.
//
// FAILURE 3 — 4 final_span_unclosed: nearBudgetThreshold=30 gave CloseSpanWithinBudget
//   too little budget to complete complex multi-variable expressions.
//   FIX: Increase nearBudgetThreshold to 50.
//
// FAILURE 4 — API violation in best attempt (18): used `next == "<<"` exact token check.
//   FIX: Use RenderedEndsWith(generated, "<<") as required by API contract.
//
// FAILURE 5 — minPreludeSteps=50 in attempt 24: partially blocked natural "<< " detection.
//   Attempt 22 proved minPreludeSteps=150 catastrophically blocked detection at median step 88.
//   FIX: Remove minPreludeSteps entirely. Guidance echoes are not observed empirically.
//
// PRESERVED FROM BEST ATTEMPT (18):
//   - Guidance with <<int(formula)>> examples (no curly braces in examples)
//   - prefixBudget = maxSteps - 100 (force-open at step 800 for 900-step budget)
//   - maxSpanTokens = 28 (allow longer multi-variable expressions)
//   - penaltyTokens = ["{", "}", "**", "^", "\\"] at 8.0 penalty
//   - CloseSpanWithinBudget on EOS-inside-span and near-budget
//   - break after first span close (evaluator uses last_visible_span)
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Branch A (outside span, UnconstrainedStep, non-EOS, RenderedEndsWith false):
//   insideConstrainedOut stays false. Implication vacuously true.
//
// Branch B (outside span, UnconstrainedStep, non-EOS, RenderedEndsWith true):
//   generated := generated + [next]; EnterObservedConstrainedSpan sets
//   insideConstrainedOut := true, currentConstrainedOut := [].
//   parser.IsValidPrefix([]) holds by method precondition. Preserved.
//
// Branch C (outside span, EOS): insideConstrainedOut stays false. Vacuously true.
//
// Branch D (outside span, force-open at prefixBudget):
//   OpenConstrainedSpan sets insideConstrainedOut := true, currentConstrainedOut := [].
//   parser.IsValidPrefix([]) by precondition. Preserved.
//
// Branch E (inside span, nearBudget <= 50 or spanTokens >= maxSpanTokens):
//   CloseSpanWithinBudget postcondition:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). Preserved.
//
// Branch F (inside span, CloseSpanIfComplete closed=true):
//   insideConstrainedOut := false; implication vacuously true. Preserved.
//
// Branch G1 (inside span, |currentConstrained|==0, SafeBoostedConstrainedStep, non-EOS):
//   SafeBoostedConstrainedStep hard-masks to parser-valid tokens plus EOS by contract.
//   AppendConstrainedToken appends next to currentConstrainedOut, preserving IsValidPrefix.
//
// Branch G2 (inside span, |currentConstrained|>0, AdaptiveConstrainedStepWithPenalties, non-EOS):
//   AdaptiveConstrainedStepWithPenalties hard-masks to parser-valid tokens plus EOS.
//   AppendConstrainedToken preserves IsValidPrefix. Preserved.
//
// Branch H (inside span, EOS from constrained step):
//   CloseSpanWithinBudget postcondition guarantees validity. Preserved.
//
// Invariant 2: |generated| <= |generatedPrefix| + steps
//
// Branch A (UnconstrainedStep, non-EOS, no span entry):
//   generated += [next] (+1), steps += 1. Preserved.
// Branch B (UnconstrainedStep, RenderedEndsWith true):
//   generated += [next] (+1), steps += 1. EnterObservedConstrainedSpan: no append, +0 cost. Preserved.
// Branch C (EOS unconstrained): steps += 1, no append. Preserved.
// Branch D (OpenConstrainedSpan): appends exactly 1 token "<<", steps += 1. Preserved.
// Branch E (CloseSpanWithinBudget, near budget or spanTokens >= max):
//   closeBudget = remainingBudget = maxSteps - steps_before.
//   |generated| grows at most closeBudget; steps grows by closeBudget to maxSteps. Preserved.
// Branch F (CloseSpanIfComplete closed=true): appends at most 1 ">>" token, steps += 1. Preserved.
// Branch G1/G2 (CloseSpanIfComplete closed=false => constrained step => AppendConstrainedToken):
//   CloseSpanIfComplete costs 0 when not closing; steps += 1 accounts for the constrained step (+1).
//   AppendConstrainedToken: 0 cost, appends 1 token to generated.
//   Net: |generated| grows by 1, steps grows by 1. Preserved.
// Branch H (EOS inside span => CloseSpanWithinBudget):
//   rem = maxSteps - steps; steps grows by rem to maxSteps; |generated| grows at most rem. Preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

// Guidance WITH <<int(...)>> so the model uses delimiters, WITHOUT curly braces
// in the examples (which confuse the parser) and WITHOUT loose "expression" placeholders.
var guidance: string := "Solve step by step. Use variable names from the problem WITHOUT curly braces. End with exactly one <<int(formula)>> where formula uses the actual variable names. Examples: <<int(n * p)>>, <<int(a - b * c)>>, <<int(total // count)>>. Use only +, -, *, /, //, %. No ** or ^.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var prefixBudget: nat := if maxSteps > 200 then maxSteps - 100 else (if maxSteps > 100 then maxSteps - 30 else maxSteps / 2);
var penaltyTokens: seq<Token> := ["{", "}", "**", "^", "\\"];
var spanTokens: nat := 0;
var maxSpanTokens: nat := 28;
var nearBudgetThreshold: nat := 50;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var remainingBudget := maxSteps - steps;
    if steps >= prefixBudget && remainingBudget > 5 {
      // Force-open constrained span if model hasn't opened one naturally
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
      spanTokens := 0;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        // RenderedEndsWith handles space-prefixed or split << tokens (API compliance).
        if RenderedEndsWith(generated, "<<") {
          var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := eg;
          insideConstrainedOut := ei;
          currentConstrainedOut := ec;
          spanTokens := 0;
        }
      }
    }
  } else {
    // Inside constrained span
    var remainingBudget := maxSteps - steps;

    // Emergency close: near budget end or span getting too long
    if remainingBudget <= nearBudgetThreshold || spanTokens >= maxSpanTokens {
      if remainingBudget > 0 {
        var sg, si, sc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
        );
        generated := sg;
        insideConstrainedOut := si;
        currentConstrainedOut := sc;
        steps := steps + remainingBudget;
      }
      break;
    }

    // Try to close if the constrained expression is complete (costs 1 step)
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      break;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next: Token;
      if |currentConstrainedOut| == 0 {
        // Boost "int" as the first constrained token to prevent tiny 1-token bare-variable spans.
        // The parser won't accept int(...) as complete until the closing ) is generated,
        // forcing multi-token spans and correct formula structure.
        next := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, ["int"], 6.0, eosToken);
      } else {
        next := helpers.AdaptiveConstrainedStepWithPenalties(
          lm, parser, constrainedPrompt, currentConstrainedOut,
          validTokenGroups, 2.0,
          penaltyTokens, 8.0,
          6, eosToken
        );
      }
      if next == eosToken {
        // EOS inside constrained span: force close with all remaining budget
        var rem := maxSteps - steps;
        if rem > 0 {
          var sg2, si2, sc2 := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem
          );
          generated := sg2;
          insideConstrainedOut := si2;
          currentConstrainedOut := sc2;
          steps := steps + rem;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        spanTokens := spanTokens + 1;
      }
    }
  }
}

